-- US English (founder, 2026-10-10: "switch the whole product to US English and US dates"). New businesses get the US
-- copy from the code; this brings rows written before the switch into line where they still hold the old default text
-- word for word, so nothing a founder wrote or edited is touched. Identifiers stay (agent_type 'categoriser', skill keys
-- such as 'prioritisation', the 'organisation' entity kind, tab slug 'wage-bill').
--
-- 1. The Finance tab the founder reads as "Payroll" (MODULE_TABS), where the stored title is still the old default.
update screen_definitions set title = 'Payroll', updated_at = now() where tab_slug = 'wage-bill' and title = 'Wage bill';
--> statement-breakpoint
